/**
 * @suppress
 */
public object FfiConverterTypeMdbxVault: FfiConverter<MdbxVault, Long> {
    override fun lower(value: MdbxVault): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): MdbxVault {
        return MdbxVault(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): MdbxVault {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: MdbxVault) = 8UL

    override fun write(value: MdbxVault, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



